#!/usr/bin/env node
/**
 * build-bundled-agency.cjs — committed generator for src/bundledAgencyData.js.
 *
 * OFFLINE TWIN of the live `processAgencyDailyLogTab` / `parseAgencyChannelSales`
 * in src/lib/uploadParsers.js. Reads the founder's Agency "Channel-wise Sales
 * Sheet" (multi-tab xlsx: "AMZ Categorywise", "Blinkit Categorywise",
 * "FK Categorywise") and bakes the per-SKU, per-channel sales buckets + growth
 * into the committed bundle data.js layers on at load.
 *
 * WHY THIS EXISTS (P0-1 / P1-7): the bundle was previously generated by an
 * inline node command that drifted — it lacked `sales14d` (D5 MAX(30,14)
 * velocity), lacked the `monthly[]` ladder (max-trailing-MoM growth, §3.5), and
 * dropped NSACDT30 (Acacia Catechu). data.js silently fell back to single-MoM
 * growth and a 1.0/d orders proxy. This script is the durable, committed source
 * so the bundle can be regenerated deterministically and never drifts again.
 *
 * KEEP IN SYNC with src/lib/uploadParsers.js (the live browser parser). Any
 * change to AGENCY_NAME_MAP / bucket math / monthly ladder there must be
 * mirrored here, and vice versa.
 *
 * Usage:
 *   node scripts/build-bundled-agency.cjs ["<path-to-agency-xlsx>"]
 * Default input: the founder's daily-sales workbook in ~/Downloads.
 */
const fs = require("fs");
const path = require("path");
const os = require("os");
const XLSX = require("xlsx");

const DEFAULT_INPUT = path.join(
  os.homedir(),
  "Downloads",
  "NS - inventory - Amazon, Flipkart, Blinkit Daily Sales of all SKUs.xlsx"
);
const OUTPUT = path.join(__dirname, "..", "src", "bundledAgencyData.js");

// ─── Agency category display name → canonical SKU code ───────────────────────
// MIRROR of AGENCY_NAME_MAP in src/lib/uploadParsers.js.
const AGENCY_NAME_MAP = {
  "jatamansi oil":                "NSJO100",
  "sea buckthorn berries 100g":   "NSSBDB100",
  "sea buckthorn berries 250g":   "NSSBDB250",
  "sea buckthorn berries 500g":   "NSSBDB500",
  "sea buckthorn powder 100g":    "NSSB100",
  "sea buckthorn powder 250g":    "NSSB250",
  "sea buckthorn powder 500g":    "NSSB500",
  "sea buckthorn oil 15ml":       "NSSBBO15",
  "sea buckthorn oil 30ml":       "NSSBBO30",
  "sea buckthorn juice 300ml":    "NSSBJ300",
  "sea buckthorn juice 500ml":    "NSSBJ500",
  "moringa powder 100g":          "NSMP100",
  "moringa powder 250g":          "NSMP250",
  "acacia catechu":               "NSACDT30",
};

const num = (v) => {
  if (typeof v === "number") return Number.isFinite(v) ? v : 0;
  const s = String(v || "").trim();
  if (!s || /^na$/i.test(s)) return 0;
  const n = Number(s.replace(/[^0-9.\-]/g, ""));
  return Number.isFinite(n) ? n : 0;
};

function normalizeAgencyName(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[()]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// "Jatamansi Oil*4" → { code: NSJO100, multiplier: 4 }; single → multiplier 1.
function mapAgencyColumnToCode(header) {
  const norm = normalizeAgencyName(header);
  if (!norm || norm === "total") return null;
  const m = norm.match(/^(.+?)\s*\*\s*(\d+)$/);
  if (m) {
    const code = AGENCY_NAME_MAP[m[1].trim()];
    return code ? { code, multiplier: parseInt(m[2], 10) || 1 } : null;
  }
  const code = AGENCY_NAME_MAP[norm];
  return code ? { code, multiplier: 1 } : null;
}

function detectAgencyChannel(tabName) {
  const lc = String(tabName || "").toLowerCase();
  if (/amz|amazon|fba/.test(lc))     return "amazon";
  if (/blink|blnkit|quick/.test(lc)) return "blinkit";
  if (/flip|^fk|flipkart/.test(lc))  return "flipkart";
  return null;
}

function parseSheetDate(v) {
  if (v == null || v === "") return null;
  if (v instanceof Date) return v;
  if (typeof v === "number") return new Date((v - 25569) * 86400 * 1000);
  const s = String(v).trim();
  if (!s || /^total/i.test(s)) return null;
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return new Date(`${m[3]}-${String(m[2]).padStart(2, "0")}-${String(m[1]).padStart(2, "0")}`);
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

// MIRROR of processAgencyDailyLogTab in src/lib/uploadParsers.js (no cutoff).
function processAgencyDailyLogTab(ws, channel, byCode) {
  const grid = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "", raw: true });
  if (!grid.length) return false;

  let headerIdx = -1;
  for (let i = 0; i < Math.min(grid.length, 10); i++) {
    if (normalizeAgencyName(grid[i][0]) === "date") { headerIdx = i; break; }
  }
  if (headerIdx === -1) return false;
  const headers = grid[headerIdx];

  const colMap = {};
  for (let c = 1; c < headers.length; c++) {
    const m = mapAgencyColumnToCode(headers[c]);
    if (m) colMap[c] = m;
  }
  if (Object.keys(colMap).length === 0) return false;

  const dataRows = grid.slice(headerIdx + 1);
  let latestTs = -Infinity;
  for (const r of dataRows) {
    const d = parseSheetDate(r[0]);
    if (!d) continue;
    latestTs = Math.max(latestTs, d.getTime());
  }
  if (!Number.isFinite(latestTs)) return false;

  for (const r of dataRows) {
    const d = parseSheetDate(r[0]);
    if (!d) continue;
    const ageDays = (latestTs - d.getTime()) / 86400000;
    if (ageDays < 0 || ageDays > 120) continue;
    for (const col of Object.keys(colMap)) {
      const { code, multiplier } = colMap[col];
      const val = num(r[col]) * multiplier;
      if (!byCode[code]) byCode[code] = {};
      if (!byCode[code][channel]) byCode[code][channel] = { sales7d: 0, sales14d: 0, sales15d: 0, sales30d: 0, sales60d: 0, sales90d: 0, sales120d: 0 };
      const tgt = byCode[code][channel];
      if (ageDays <=   7) tgt.sales7d   += val;
      if (ageDays <=  14) tgt.sales14d  += val;
      if (ageDays <=  15) tgt.sales15d  += val;
      if (ageDays <=  30) tgt.sales30d  += val;
      if (ageDays <=  60) tgt.sales60d  += val;
      if (ageDays <=  90) tgt.sales90d  += val;
      if (ageDays <= 120) tgt.sales120d += val;
    }
  }

  for (const code of Object.keys(byCode)) {
    const t = byCode[code][channel];
    if (!t) continue;
    t.dailyOut = +(t.sales30d / 30).toFixed(3);
    const prior30 = Math.max(0, t.sales60d - t.sales30d);
    if (prior30 > 0)                             t.growth = Math.max(-100, Math.min(200, ((t.sales30d - prior30) / prior30) * 100));
    else if (t.sales30d > 0)                     t.growth = 200;
    else if (prior30 === 0 && t.sales30d === 0)  t.growth = null;
    else                                         t.growth = -100;
    if (t.growth != null) t.growth = Math.round(t.growth * 10) / 10;
    const s30  = Number.isFinite(t.sales30d)  ? t.sales30d  : 0;
    const s60  = Number.isFinite(t.sales60d)  ? t.sales60d  : 0;
    const s90  = Number.isFinite(t.sales90d)  ? t.sales90d  : 0;
    const s120 = Number.isFinite(t.sales120d) ? t.sales120d : 0;
    t.monthly = [s30, s60 - s30, s90 - s60, s120 - s90];
    delete t.sales90d;
    delete t.sales120d;
  }
  return true;
}

// ─── Run ─────────────────────────────────────────────────────────────────────
const INPUT = process.argv[2] || DEFAULT_INPUT;
if (!fs.existsSync(INPUT)) {
  console.error(`build-bundled-agency: input not found: ${INPUT}`);
  process.exit(1);
}
const wb = XLSX.readFile(INPUT);
const channelTabs = wb.SheetNames
  .map((name) => ({ name, channel: detectAgencyChannel(name) }))
  .filter((x) => x.channel);
if (!channelTabs.length) {
  console.error("build-bundled-agency: no channel-named tabs (AMZ/Blinkit/FK Categorywise) found.");
  process.exit(1);
}

const byCode = {};
let latestOverall = -Infinity;
for (const { name, channel } of channelTabs) {
  const ws = wb.Sheets[name];
  // Track the latest date across tabs for snapshotDate.
  const grid = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "", raw: true });
  for (const r of grid.slice(1)) {
    const d = parseSheetDate(r[0]);
    if (d) latestOverall = Math.max(latestOverall, d.getTime());
  }
  const ok = processAgencyDailyLogTab(ws, channel, byCode);
  console.error(`  ${name} → ${channel}: ${ok ? "ok" : "skipped"}`);
}

const snapshotDate = Number.isFinite(latestOverall)
  ? new Date(latestOverall).toISOString().slice(0, 10)
  : null;

// Round sales buckets to integers (they are summed daily counts; the daily-log
// stores fractional averages in some rows, so round on emit for a clean bundle).
for (const code of Object.keys(byCode)) {
  for (const ch of Object.keys(byCode[code])) {
    const t = byCode[code][ch];
    for (const k of ["sales7d", "sales14d", "sales15d", "sales30d", "sales60d"]) {
      if (Number.isFinite(t[k])) t[k] = Math.round(t[k]);
    }
    if (Array.isArray(t.monthly)) t.monthly = t.monthly.map((x) => (Number.isFinite(x) ? Math.round(x) : 0));
  }
}

const banner = `/**
 * bundledAgencyData.js — auto-generated from the founder's Agency
 * Channel-wise Sales Sheet. DO NOT hand-edit. Regenerate via
 * \`node scripts/build-bundled-agency.cjs <path-to-xlsx>\`.
 *
 * Shape: { snapshotDate, byCode: { <canonical>: { amazon | blinkit | flipkart:
 *   { sales7d, sales14d, sales15d, sales30d, sales60d, dailyOut, growth,
 *     monthly:[m0,m1,m2,m3] } } } }
 *   - sales14d  → D5 MAX(30d,14d) velocity window.
 *   - monthly[] → trailing-30d sums, MOST-RECENT FIRST → max-trailing-MoM growth.
 *
 * Per founder's truth table, this is the source-of-truth for Amazon channel
 * velocity + growth (and a fallback for Flipkart/Blinkit when their native
 * exports are missing). data.js layers a live upload on top of this baseline.
 */
`;

const out = banner + "export const BUNDLED_AGENCY_DATA = " +
  JSON.stringify({ snapshotDate, byCode }, null, 2) + ";\n";
fs.writeFileSync(OUTPUT, out);
console.error(`build-bundled-agency: wrote ${OUTPUT} (snapshot ${snapshotDate}, ${Object.keys(byCode).length} SKUs)`);
